package com.bank.counter.service;

import java.util.logging.Logger;

// Greedy change-making: dispense larger notes first, hoard the fives.
public class CounterChangeService {
    private static final Logger log = Logger.getLogger(CounterChangeService.class.getName());

    public boolean canServeAll(int[] payments) {
        int fives = 0, tens = 0;                           // twenties are never used as change
        for (int pay : payments) {
            if (pay == 5) {
                fives++;                                    // no change needed
            } else if (pay == 10) {
                if (fives == 0) { logFail(pay); return false; }
                fives--; tens++;                            // give one five as change
            } else { // pay == 20, owe 15
                if (tens > 0 && fives > 0) { tens--; fives--; }   // prefer 10 + 5
                else if (fives >= 3) { fives -= 3; }              // else three 5s
                else { logFail(pay); return false; }
            }
        }
        log.info(() -> "All customers served with correct change");
        return true;
    }

    private void logFail(int pay) {
        log.warning(() -> "Cannot give change for a " + pay + " unit note");
    }
}
