package com.bank.counter;

import com.bank.counter.service.CounterChangeService;
import java.util.logging.Logger;

public class CounterChangeApplication {
    private static final Logger log = Logger.getLogger(CounterChangeApplication.class.getName());

    public static void main(String[] args) {
        CounterChangeService service = new CounterChangeService();
        int[] payments = {5, 5, 5, 10, 20};                // arrival order of notes
        boolean ok = service.canServeAll(payments);
        log.info(() -> "Can serve all customers = " + ok);
    }
}
